INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126896, 'spa', 'Dispersar en juicio', 'Verbo de significado incierto en Deuteronomio 32:26, probablemente «dispersar» o «esparcir» en el contexto del juicio divino. Los cognados árabes sugieren «hender» o «partir», mientras que la evidencia de las traducciones antiguas apoya el sentido de dispersar a Israel como castigo. La forma verbal es única y debatida, pero el contexto apunta claramente a una destrucción total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126897, 'spa', 'Lado, dirección — El sentido dominante en 72 apariciones', 'Lado, dirección — El sentido dominante en 72 apariciones: un lado o cara direccional de una estructura, territorio o frontera. Se usa extensamente en las prescripciones arquitectónicas del tabernáculo (Éx 26:18; 27:9-11) y en las visiones del templo y la repartición de tierras de Ezequiel. El término funciona casi como un indicador de orientación espacial por puntos cardinales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126903, 'spa', 'Esquina, borde — La esquina o borde de un objeto físico o área delimitada, con 9', 'Esquina, borde — La esquina o borde de un objeto físico o área delimitada, con 9 apariciones. En Levítico 19:9 y 23:22 designa la esquina del campo que debe dejarse para la espiga, un uso tan significativo que da nombre a un tratado completo de la Misná (Pe''ah). También se refiere a las esquinas de una mesa (Éx 25:26; 37:13) y a la esquina de un diván (Am 3:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126908, 'spa', 'Sien de la cabeza, patilla — La sien o zona lateral de crecimiento del cabello h', 'Sien de la cabeza, patilla — La sien o zona lateral de crecimiento del cabello humano, atestiguada 5 veces en textos proféticos y legales. Levítico 19:27 prohíbe redondear «las esquinas de vuestra cabeza», mientras que los oráculos de juicio de Jeremías (9:26; 25:23; 49:32) se dirigen contra quienes «se rapan las sienes». Números 24:17 lo emplea en el oráculo de Balaam sobre destrozar las sienes de Moab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126919, 'spa', 'Glorificar, honrar', 'Sentido transitivo del Piel: conferir honra o gloria a otro. En Isaías 55:5 y 60:9, Dios ha glorificado a Israel de modo que las naciones acuden hacia ella. El énfasis recae en dignificar o exaltar al receptor. El español ''te glorificó'' refleja con precisión este otorgamiento exterior de honor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126920, 'spa', 'Glorificarse, ser glorificado', 'Sentido reflexivo del Hitpael: adquirir o manifestar gloria, usado especialmente cuando Dios despliega su esplendor a través de su pueblo. Isaías 44:23 declara que el SEÑOR se ha glorificado en Israel, e Isa 49:3 identifica al Siervo como aquel en quien Dios será glorificado. Isa 60:21 y 61:3 lo extienden al pueblo restaurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126921, 'spa', 'Embellecer, adornar', 'Sentido Piel de embellecimiento o adorno físico. Isaías 60:13 habla de hermosear el santuario con maderas selectas, Esdras 7:27 de adornar el templo, y Salmo 149:4 de que Dios adorna a los humildes con victoria. El español ''hermosear'' distingue este sentido estético concreto de la glorificación abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126922, 'spa', 'Jactarse, vanagloriarse', 'El Hitpael en registro negativo: jactarse, vanagloriarse o gloriarse con orgullo. En Jueces 7:2, Dios reduce el ejército de Gedeón para que Israel no se jacte contra Él. Isaías 10:15 pregunta si el hacha se gloriará contra quien la maneja. Éxodo 8:9 lo emplea más neutralmente: Moisés cede a Faraón el ''honor'' de decidir cuándo partirán las ranas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126930, 'spa', 'Rebuscar las ramas', 'Significa «repasar las ramas» o «rebuscar» en el contexto de la cosecha de aceitunas. Deuteronomio 24:20 prohíbe esta práctica, exigiendo que los israelitas cosechen una sola vez y dejen las aceitunas restantes para los pobres y forasteros. El verbo se deriva de un sustantivo que significa «rama», generando el sentido específico de trabajar repetidamente entre las ramas del árbol.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126931, 'spa', 'Tocado, turbante, guirnalda', 'Ornamento para la cabeza que puede ser un turbante sacerdotal, tocado festivo o guirnalda de honor. En contextos cultuales designa los turbantes de lino del sacerdocio: ''adornos de las tiaras de lino fino'' (Éx 39:28) y los turbantes de lino prescritos para los sacerdotes del templo ideal de Ezequiel (Ez 44:18). En sentido figurado, Isaías lo emplea para la guirnalda gozosa que Dios concede a los dolientes en lugar de ceniza (Is 61:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126938, 'spa', 'ramaje o ramas grandes', 'Ramas o ramaje de un gran arbol, usados figuradamente en la alegoria profetica para representar la extension y esplendor de los imperios. En Ez 17:6 describe las ramas extendidas de una vid (la dinastia de Juda), mientras que Ez 31:5-13 lo despliega repetidamente para el imponente cedro que representa a Asiria/Egipto: sus ramas cobijan naciones (v. 6), no tienen rival en belleza (v. 8), y son destrozadas en el juicio (vv. 12-13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126939, 'spa', 'Ramaje elevado', 'Sustantivo colectivo que significa «copa» o «ramas altas», usado en Isaías 10:33 dentro de una metáfora de juicio divino. Dios cortará las «ramas»—la copa elevada que representa el liderazgo soberbio de Asiria. El término aparece con variación textual (Ketiv פארה frente a Qere פורה), pero el sentido es claro: las ramas prominentes y elevadas que serán derribadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126941, 'spa', 'Parán', 'Nombre propio de una región desértica en el noreste de la península del Sinaí, que sirvió como punto de referencia principal durante las peregrinaciones de Israel por el desierto. Se menciona como lugar de residencia de Ismael (Gn 21:21), punto de partida tras el Sinaí (Nm 10:12; 12:16) y base desde la cual se enviaron los espías a Canaán (Nm 13:3). En español se retiene la forma ''Parán'' con acento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126943, 'spa', 'Higos tempranos', 'Se refiere a los higos tempranos o brevas en su primera etapa de desarrollo. En Cantar de los Cantares 2:13, la aparición de las brevas señala la llegada de la primavera y la fertilidad del mundo, invitando al amor a florecer. Estos frutos tempranos preceden la cosecha principal y representan la promesa de la abundancia venidera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126944, 'spa', 'Carne ritualmente impura', 'Carne sacrificial ritualmente contaminada, abominable e inaceptable. Levítico 7:18 y 19:7 definen el sentido cultual técnico: la carne comida al tercer día se vuelve inmunda e invalida el sacrificio. Isaías 65:4 y Ezequiel 4:14 lo extienden a carne generalmente impura en contextos de abominación ritual. El significado constante es carne que ha pasado de aceptable a profanadora, ya sea por el tiempo o por su origen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126945, 'spa', 'Alcanzar, tocar o extenderse hasta un límite geográfico — 8 ocurrencias circunsc', 'Alcanzar, tocar o extenderse hasta un límite geográfico — 8 ocurrencias circunscritas a las descripciones de los territorios tribales en Josué 16-19. El límite de Zabulón «llegaba» hasta Sarid (Jos 19:11); la frontera de Aser «tocaba» el Carmelo (Jos 19:26). Es un uso espacial especializado, distinto del golpe violento del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126946, 'spa', 'Golpear, atacar o caer sobre alguien con intención violenta — 14 ocurrencias con', 'Golpear, atacar o caer sobre alguien con intención violenta — 14 ocurrencias concentradas en narrativas militares y judiciales. Gedeón ordena a su hijo: «¡Cae sobre ellos!» (Jue 8:21); Doeg «cayó sobre los sacerdotes» por orden de Saúl (1 S 22:18). El cognado árabe فَجَعَ (''infligir dolor'') selecciona el mismo registro de impacto violento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126949, 'spa', 'Encontrar, toparse con alguien o algo, a menudo de modo inesperado o providencia', 'Encontrar, toparse con alguien o algo, a menudo de modo inesperado o providencial — 12 ocurrencias en narrativas patriarcales y posteriores. Jacob «dio con» cierto lugar y durmió allí (Gn 28:11); se «encontró» con ángeles de Dios en Majanaim (Gn 32:1); el vengador de sangre «encuentra» al homicida (Nm 35:19, 21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126954, 'spa', 'Interceder, rogar o suplicar en favor de otro — 10 ocurrencias en literatura sap', 'Interceder, rogar o suplicar en favor de otro — 10 ocurrencias en literatura sapiencial, profética y narrativa. Los parientes de Efrón «ruegan» en favor del siervo de Abraham (Gn 23:8); Rut suplica a Noemí: «No insistas en que te deje» (Rt 1:16). El caso culminante es Is 53:12: el Siervo «intercede por los transgresores».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126964, 'spa', 'Hifil causativo', 'Hifil causativo: hacer que algo recaiga o caiga sobre alguien — 2 ocurrencias de peso teológico desproporcionado a su frecuencia. Is 53:6: «El SEÑOR hizo recaer sobre él la iniquidad de todos nosotros», la declaración central del sufrimiento vicario. Job 36:32: Dios ordena al rayo y «hace que alcance» su blanco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126981, 'spa', 'Nombre propio masculino', 'Pagiel (''encuentro de Dios''), hijo de Ocrán, jefe designado de la tribu de Aser durante el desierto. Aparece exclusivamente en Números en contextos administrativos y ceremoniales: el censo (Nm 1:13), la disposición del campamento (Nm 2:27), su ofrenda de dedicación del tabernáculo el undécimo día (Nm 7:72, 77) y el orden de marcha (Nm 10:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126983, 'spa', 'Cuerpo sin vida, humano o animal, generalmente expuesto o insepulto', 'Cuerpo sin vida, humano o animal, generalmente expuesto o insepulto. La gran mayoría de las ocurrencias son plurales, describiendo muerte masiva en guerras o castigo divino: los asirios muertos (2 Reyes 19:35 = Isaías 37:36) y la generación del desierto (Números 14:29). El uso colectivo singular en 1 Samuel 17:46 y Amós 8:3 intensifica la imagen de matanza generalizada. Levítico 26:30 habla figuradamente de los ''cadáveres de vuestros ídolos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127000, 'spa', 'Encontrarse mutuamente (Nifal)', 'Sentido recíproco del Nifal: dos partes se encuentran o convergen. El caso más célebre es Salmo 85:10, donde ''la misericordia y la verdad se encontraron'', personificación poética de cualidades abstractas en armonía. Proverbios 22:2 y 29:13 usan la misma forma para señalar que ricos y pobres ''se encuentran'', ambos hechos por el SEÑOR.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127001, 'spa', 'Encontrar, hallar (Qal)', 'Sentido básico del Qal: encontrar o encontrarse con alguien, usado transitivamente. El siervo de Jacob ensaya qué decir cuando Esaú ''te encuentre'' (Gn 32:17), el SEÑOR encuentra a Moisés en la posada (Éx 4:24), Aarón encuentra a Moisés en el monte de Dios (Éx 4:27) y Abigail se topa con David (1 Sam 25:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127011, 'spa', 'Toparse, dar con (Piel)', 'Sentido de toparse con alguien de forma fortuita o inesperada, distinguido de los encuentros deliberados del sentido 1 por su contexto de oscuridad y confusión. En Job 5:14, los necios ''se topan con'' las tinieblas en pleno día y andan a tientas al mediodía como si fuera de noche. El encuentro aquí no es intencional sino accidental o fatídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127012, 'spa', 'Redimir o rescatar (Qal activo) — El significado central del Qal activo', 'Redimir o rescatar (Qal activo) — El significado central del Qal activo: redimir o rescatar pagando un precio, librando de la esclavitud, el peligro o la muerte. Abarca desde la ley cultual (rescatar a un primogénito, Éx 13:13; Nm 18:15-16) hasta la liberación nacional (Dios redimiendo a Israel de Egipto, Dt 9:26; 2 S 7:23) y el rescate personal (Sal 25:22; 26:11; 49:7-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127022, 'spa', 'Los redimidos (participio pasivo Qal) — El participio pasivo Qal usado como sust', 'Los redimidos (participio pasivo Qal) — El participio pasivo Qal usado como sustantivo: «los redimidos», aquellos que han sido rescatados. Isaías 35:10 y 51:11 —«los rescatados de Jehová volverán»— son los pasajes definitorios, donde el participio se convierte en título de honor para el pueblo liberado de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127024, 'spa', 'Permitir la redención (Hifil causativo) — Una forma Hifil causativa en Éx 21', 'Permitir la redención (Hifil causativo) — Una forma Hifil causativa en Éx 21:8: si un amo está descontento con una sierva, «permitirá que sea redimida», causando o permitiendo su redención por un tercero. El matiz causativo señala que el amo no la redime él mismo, sino que posibilita la transacción. Esta variante legal-procedimental se distingue de la redención directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127025, 'spa', 'El que redime (participio activo Qal) — El participio activo Qal usado como sust', 'El que redime (participio activo Qal) — El participio activo Qal usado como sustantivo: «el que redime», el agente redentor. Dt 13:5 identifica a Dios como «el que te redimió» de Egipto, y Sal 34:22 declara que «Jehová redime el alma de sus siervos». Esta forma participial destaca la actividad continua y característica del redentor, no un solo acto pasado sino un atributo definitorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127032, 'spa', 'Ser redimido (Nifal pasivo) — El Nifal pasivo', 'Ser redimido (Nifal pasivo) — El Nifal pasivo: ser redimido o rescatado, donde el sujeto recibe la acción de la redención. Lv 19:20 (una esclava «no redimida aún»), Lv 27:29 (una persona consagrada que «no será rescatada») e Is 1:27 («Sión será redimida con justicia») ilustran el rango desde el estatus legal hasta la promesa profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127040, 'spa', 'Siendo redimida (participio pasivo estativo) — Una forma participial pasiva Qal ', 'Siendo redimida (participio pasivo estativo) — Una forma participial pasiva Qal en Lv 19:20 usada adverbialmente o como cláusula circunstancial: «y siendo redimida» (o «aunque aún no redimida»), describiendo el estado de una mujer esclava. Aunque se superpone con el Nifal pasivo del sentido 3, esta forma funciona como un modificador descriptivo dentro del caso legal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127049, 'spa', 'Príncipe de Neftalí', 'El nombre propio «Pedahel» identifica al príncipe de Neftalí encargado de supervisar la repartición de la tierra en Números 34:28. El nombre significa «Dios ha rescatado», reflejando el tema teológico de la redención divina habitual en la nomenclatura israelita. Pedahel fue uno de los líderes tribales responsables de repartir equitativamente la Tierra Prometida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127050, 'spa', 'Pedahzur (nombre propio)', 'El nombre propio Pedahzur (פְּדָהצוּר), que significa ''la Roca ha redimido'', identifica al padre manasita de Gamaliel. Sus seis apariciones se encuentran en Números, en contextos de censo y ofrendas. La LXX lo transcribe como Φαδασσουρ. Las traducciones al español y otras lenguas mantienen la transliteración, reflejando su identidad estable como nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127053, 'spa', 'Redimidos o rescate', 'Los redimidos o su precio de redención en la sustitución levítica. Números 3:46, 48, 49, 51 documentan la redención de 273 primogénitos israelitas excedentes respecto al conteo de levitas. El término se refiere tanto a los individuos redimidos como a la plata recaudada (1.365 siclos en total). La ambigüedad entre personas y pago refleja cómo la transacción redentora identifica a las personas con su rescate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127055, 'spa', 'Redención divina', 'Redención o liberación, ya sea mediante rescate o acción divina. Éxodo 8:23 podría emplearlo para la distinción salvífica que separa a Israel de Egipto (texto incierto). Los Salmos celebran la redención de Dios: enviar liberación a su pueblo (111:9) y ofrecer redención del pecado (130:7). Isaías 50:2 defiende el poder de Dios para redimir del exilio. El término une los aspectos transaccionales y pactales de la redención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127056, 'spa', 'Pedaías (nombre personal)', 'Nombre personal teofórico que significa ''YHWH ha rescatado'', derivado de la raíz פדה (redimir). Llevado por al menos seis individuos: el suegro de Josías (2 Re 23:36), un hijo de Jeconías y posible padre de Zorobabel (1 Cr 3:18-19), un oficial manasita que usa la forma larga Pedayahu (1 Cr 27:20), un constructor del muro en la época de Nehemías (Neh 3:25), un participante en la lectura pública de la Torá (Neh 8:4) y un colono benjamita en Jerusalén (Neh 11:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127060, 'spa', 'Dinero de rescate', 'Se refiere al dinero de redención pagado por los primogénitos israelitas en Números 3:49. Moisés recaudó la plata de rescate por los 273 primogénitos que excedían el número de levitas, quienes servían como sustitutos. Aunque la forma nominal es textualmente disputada, el concepto es claro: un pago que libera de una obligación sagrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127062, 'spa', 'Padán-Aram (topónimo)', 'Nombre geográfico propio de la región en torno a Harán en la alta Mesopotamia (actual sureste de Turquía / norte de Siria). Aparece casi exclusivamente en las narrativas patriarcales, identificando el origen de Rebeca (Gn 25:20) y el destino de Jacob al huir de Esaú (Gn 28:2, 5, 6, 7). En español se conserva la forma ''Padán-Aram'', manteniendo ambos elementos del nombre compuesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127066, 'spa', 'Redención imperativa', 'Forma verbal que significa ''redímelo'' o ''líbralo'' en Job 33:24, donde Elihú describe la intervención misericordiosa de Dios para salvar a un sufriente de la fosa. Expresa el mandato o decisión divina de rescatar a alguien de la muerte. El contexto enfatiza la misericordia de Dios cuando un mediador intercede, deteniendo la destrucción del afligido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127067, 'spa', 'Grasa sacrificial selecta', 'Se refiere a la grasa interior selecta de un animal sacrificial, especialmente la grasa dura que rodea los órganos vitales. Levítico 1:8 instruye a los sacerdotes disponer ''la cabeza y el sebo'' (הַפָּדֶר) sobre la leña encendida; el versículo 12 repite esto para el holocausto, y Levítico 8:20 lo incluye en la consagración de Aarón por Moisés. Esta grasa se consideraba la porción especial de Yahveh (Levítico 3:16) y siempre se quemaba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127068, 'spa', 'boca (parte del cuerpo)', 'La boca física literal aparece en 395 pasajes, abarcando el comer, el hablar y todas las frases pronominales y preposicionales donde el referente es el órgano corporal. Esta acepción fundacional ancla la red semántica de la que derivan los demás significados mediante metáfora y metonimia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127069, 'spa', 'filo de espada', 'El ''filo de la espada'' (לְפִי חֶרֶב) ocurre 47 veces como expresión fija para la muerte violenta. La evidencia multilingüe muestra lexemas diferenciados: árabe حَدّ (filo cortante), coreano 칼날 (hoja), suajili makali (agudeza), hindi dhaar (borde cortante), confirmando una extensión metafórica estable de boca a filo de arma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127083, 'spa', 'conforme a, según', 'La locución preposicional עַל-פִּי (''conforme a, según, en proporción a'') aparece 28 veces en contextos legales y cultuales. Los datos interlingüísticos revelan preposiciones especializadas: árabe حَسَب, coreano 따라 (siguiendo), suajili kulingana na (de acuerdo con), mostrando un significado gramaticalizado distinto de la parte corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127117, 'spa', 'extremo, confín', 'La acepción ''extremo'' o ''confín'' de una extensión espacial ocurre 4 veces (2 R 10:21; 21:16; Esd 9:11 dos veces). Árabe طَرَف, coreano 끝, suajili upande, hindi chhor significan todos borde/extremo, avalando una extensión metafórica de boca como apertura frontal a término de un límite.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127120, 'spa', 'mandato, decreto', 'Uso metonímico para ''mandato'' o ''decreto'' (la boca representando lo que de ella procede) con 6 apariciones, especialmente con sujeto divino. Las glosas interlingüísticas incluyen árabe أمر (mandato), coreano 명령 (decreto), suajili amri/neno (mandato/palabra), confirmando una vía metonímica reconocida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127122, 'spa', 'abertura, entrada', 'La abertura de un recipiente (pozo, saco, cueva) suma 12 apariciones. Las traducciones emplean términos contextuales: árabe فَتْحَة (abertura), coreano 입구 (entrada), suajili shimo/mlango (agujero/puerta), hindi mukh (boca/abertura), indicando una extensión semántica natural del orificio corporal a la apertura inanimada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127134, 'spa', 'porción, parte medida', 'La ''porción'' proporcional o parte medida aparece 3 veces (Dt 21:17 doble porción, 2 R 2:9, Zac 13:8). Evidencia multilingüe: árabe ضِعْفَيْن/ثُلْثًا (doble/tercio), coreano 배 (múltiplo), suajili sehemu/fungu (parte/porción), mostrando una locución de conteo especializada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127172, 'spa', 'cuello de vestidura', 'El ''cuello'' o abertura del escote de una prenda ocurre dos veces (Job 30:18; Sal 133:2). Las traducciones específicas incluyen árabe فَم (en sentido textil), coreano 옷깃 (abertura de vestidura), suajili ukingo/shingo (borde/cuello), confirmando este término como vocabulario especializado de indumentaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127179, 'spa', 'pim (unidad de peso)', 'Una sola aparición en 1 Samuel 13:21 (pim, unidad de peso o medida) cuyo significado permanece incierto. Este hápax legómenon se translitea en todas las lenguas (pim), lo que sugiere que los traductores lo reconocieron como término técnico cuyo referente exacto es discutido, posiblemente un peso fraccionario para afilar herramientas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127198, 'spa', 'Aquí — Adverbio deíctico que indica ubicación presente', 'Aquí — Adverbio deíctico que indica ubicación presente: «aquí, en este lugar». Se usa cuando un hablante llama la atención sobre el punto inmediato, como cuando Abraham ordena a sus siervos quedarse «aquí» (Gn 22:5) o José se identifica ante sus hermanos «aquí» en Egipto (Gn 45:12). Las 47 apariciones reflejan consistentemente este sentido locativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127199, 'spa', 'De aquí — Adverbio de origen o dirección', 'De aquí — Adverbio de origen o dirección: «de aquí, de este lugar», a menudo emparejado con complementos espaciales para describir movimiento desde un punto de referencia. Destaca en la visión del templo de Ezequiel (Ez 40:10, 12), donde las medidas se toman «de aquí y de aquí» (a cada lado). El español alterna entre «de aquí» y «de allí», revelando el matiz direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127202, 'spa', 'Nombre isacarita', 'Nombre propio de un ancestro isacarita y del padre de un juez. Génesis 46:13 y 1 Crónicas 7:1 nombran a Puá entre los hijos de Isacar, fundador del clan funita (Nm 26:23). Jueces 10:1 lo registra como padre (o ancestro) del juez Tolá. Las variantes ortográficas (Puá/Fuvá) y la diversidad en la LXX indican fluidez textual, pero el nombre designa claramente un linaje isacarita y una herencia judicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127203, 'spa', 'Entumecerse o desfallecer', 'Quedar entumecido, desfallecer o perder vitalidad por conmoción o agotamiento. Génesis 45:26 describe el corazón de Jacob entumecido de incredulidad. Salmo 38:8 expresa el entumecimiento por angustia y gemidos. Salmo 77:2 relata la mano adormecida en la noche. Habacuc 1:4 lo aplica a la justicia paralizada. El sentido constante es la pérdida de función normal bajo presión abrumadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127204, 'spa', 'Cese del llanto', 'Se refiere al descanso, cese o respiro, particularmente en el contexto del llanto. En Lamentaciones 2:18 se insta a que las lágrimas no encuentren descanso, es decir, que el llanto por la destrucción de Jerusalén continúe sin pausa. El sustantivo deriva de un verbo que significa ''entumecerse'' o ''cesar'', y expresa la idea de hacer una pausa o encontrar alivio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127205, 'spa', 'Exhalar palabras, proferir', 'Sentido figurado del Hifil donde el aliento se convierte en palabras. Proverbios empareja repetidamente este verbo con ''mentiras'' o ''verdad'': un testigo fiel ''exhala'' lo recto (Pr 12:17), mientras que un testigo falso ''exhala'' engaño (Pr 14:5; 19:5). El español ''profiere/declara'' capta cómo el habla se exhala literalmente del cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127207, 'spa', 'Soplar, respirar sobre', 'El significado nuclear literal: viento o aliento que se mueve sobre algo. Cantar de los Cantares 4:16 invita al viento del norte a ''soplar sobre'' el jardín para que fluyan sus fragancias. Cantares 2:17 y 4:6 describen la brisa vespertina. Ezequiel 21:31 presenta a Dios soplando el fuego de su ira.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127211, 'spa', 'Jadear, anhelar', 'Respiración acelerada por la anticipación o el anhelo. Habacuc 2:3 declara que la visión ''jadea hacia su cumplimiento'' — ciertamente vendrá. Salmo 12:5 describe a los oprimidos que ''jadean'' por liberación. El español ''jadear'' hace vívida la intensidad física: no es una respiración tranquila sino el aliento urgente de quien se esfuerza por alcanzar algo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127213, 'spa', 'Avivar llama, encender', 'Soplar sobre brasas para encenderlas, extendido a atizar conflictos. Proverbios 29:8 advierte que los burladores ''encienden'' la ciudad, usando este verbo de aliento para evocar la imagen de soplar sobre ascuas hasta que prenden. El español ''encienden'' traza con precisión la metáfora: los agitadores sociales son fuelles que avivan tensiones latentes hasta convertirlas en conflagración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127214, 'spa', 'Bufar con desprecio', 'Una exhalación despectiva dirigida contra los enemigos. Salmo 10:5 describe al malvado que ''sopla'' contra todos sus adversarios, un gesto de desdén arrogante, como si los dispersara como polvo. El contexto del retrato sálmico del opresor soberbio muestra que aquí el aliento se usa no para encender ni hablar, sino para menospreciar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127215, 'spa', 'Put (pueblo y territorio)', 'Nombre propio פּוּט que designa un pueblo y territorio descendiente de Cam, tercer hijo tras Cus y Mizraim en la Tabla de las Naciones (Gn 10:6; 1 Cr 1:8). Identificado con una región norteafricana, posiblemente Libia. En los textos proféticos aparece como potencia militar aliada de Egipto: guerreros portadores de escudos (Jer 46:9) y mercenarios en Tiro (Ez 27:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127217, 'spa', 'Nombre propio', 'Nombre propio que identifica al padre de la mujer que se casó con Eleazar, hijo de Aarón (Éxodo 6:25). Putiel fue así el abuelo de Finees, el sacerdote que más tarde demostró gran celo por Dios en Sitim. La etimología del nombre es oscura, pero podría reflejar influencia egipcia, algo apropiado para una generación nacida en Egipto antes del éxodo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127219, 'spa', 'Sacerdote de On', 'Nombre personal de un sacerdote egipcio que servía en On (Heliópolis), identificado como suegro de José. Génesis 41:45 registra que Faraón dio a José ''a Asenat hija de Potifera sacerdote de On'' como esposa. El versículo 50 nota que antes de la hambruna, José tuvo dos hijos ''que le dio a luz Asenat hija de Potifera sacerdote de On'', y 46:20 repite este detalle. El nombre es genuinamente egipcio, significando ''aquel a quien Ra ha dado''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127220, 'spa', 'Antimonio o cosmético ocular', 'Antimonio o pintura ocular (kohl) empleado con fines cosméticos y ornamentales. 2 Reyes 9:30 muestra a Jezabel pintándose los ojos. Jeremías 4:30 condena embellecerse con cosmético ante el desastre. 1 Crónicas 29:2 lo incluye entre materiales del templo. Isaías 54:11 lo usa metafóricamente para la hermosa restauración de Jerusalén. La sustancia sirve tanto para adorno personal como para ornamentación arquitectónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127222, 'spa', 'Pul, rey de Asiria', 'Pul, rey de Asiria (Tiglat-piléser III), quien invadió Israel y le exigió tributo. 2 Reyes 15:19 registra la invasión de Pul durante el reinado de Manahem y el tributo pagado. 1 Crónicas 5:26 menciona a Pul junto a «Tilgat-pilneser» en el contexto de la deportación de las tribus transjordanas. Isaías 66:19 podría referirse a una nación lejana llamada Pul. La referencia principal es claramente el monarca asirio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127223, 'spa', 'Desamparo y confusión', 'Verbo en primera persona que expresa el estado de confusión, desamparo o agobio abrumador del salmista en el Salmo 88:15. Sintiéndose abandonado por Dios desde su juventud, declara ''estoy desamparado'' o ''estoy aturdido''. El significado de la raíz es incierto pero implica estar abrumado, desorientado o incapaz de actuar ante la angustia extrema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127224, 'spa', 'Gentilicio clan isacarita', 'Designación gentilicia que identifica al clan descendiente de פּוּאָה (Puá), hijo de Isacar, en Números 26:23. El término aparece en el censo del desierto, organizando a los descendientes de Isacar en grupos familiares. Los punitas constituían uno de los clanes de Isacar, fundamentales para la distribución territorial, la organización militar y el mantenimiento de los registros genealógicos tribales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127226, 'spa', 'Partera hebrea heroica', 'Nombre propio femenino que identifica a una de las parteras hebreas heroicas en Éxodo 1:15, quien desafió la orden genocida del faraón. Junto con Sifrá, פּוּעָה preservó a los varones hebreos negándose a matarlos al nacer, alegando que las mujeres hebreas daban a luz antes de que llegaran las parteras. Su desobediencia fiel representa una temprana resistencia a la opresión y posibilitó la supervivencia de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127227, 'spa', 'Hifil', 'Hifil: esparcir, dispersar (causativo) — Hifil causativo: esparcir o dispersar activamente, el sentido dominante con 35 apariciones. Dios esparce a las naciones en Babel (Gn 11:8-9), dispersa a Israel entre los pueblos (Dt 4:27; Ez 20:34) y esparce a los enemigos (Sal 68:1). El peso teológico es enorme: la dispersión es el anti-tipo de la reunión del pueblo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127231, 'spa', 'Nifal', 'Nifal: ser esparcido (pasivo) — Nifal pasivo: ser esparcido o hallarse en estado de dispersión, con 16 apariciones. El sujeto sufre la dispersión en lugar de causarla: Israel «fue dispersado» en la batalla (2 S 18:8), el rebaño «fue dispersado» sin pastor (Ez 34:5-6), y el ejército de Sedequías «fue dispersado» por los babilonios (2 R 25:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127235, 'spa', 'Qal', 'Qal: esparcirse, dispersarse (intransitivo) — Qal intransitivo: esparcirse o dispersarse por propia iniciativa, incluyendo el participio pasivo Qal que significa «los dispersos». Once apariciones captan la dispersión autoiniciada: los constructores de Babel temen ser esparcidos (Gn 11:4), los enemigos se dispersan ante el arca (Nm 10:35) y Saúl ordena a las tropas «dispersarse» (1 S 14:34).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127267, 'spa', 'Hitpolel', 'Hitpolel: ser quebrantado (cósmico) — Una sola aparición en Habacuc 3:6 donde el verbo aparece en Hitpolel/Hitpael y el significado cambia de dispersión humana a quebrantamiento cósmico: los montes antiguos «se quebraron» ante la marcha teofánica de Dios. El vocabulario de destrucción en lugar del de dispersión sugiere una extensión metafórica del esparcimiento al desmoronamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127278, 'spa', 'Agente de dispersión', 'Designa al agente que dispersa o esparce, descrito en Nahúm 2:1 como el enemigo que avanza contra Nínive. ''El dispersador'' sube contra la capital asiria, amenazando con fragmentar sus defensas y dispersar sus fuerzas. El término enfatiza el papel del enemigo en la destrucción del poder de Nínive. Algunos sugieren leer ''martillo'', pero la evidencia multilingüe apoya el sentido de dispersión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127282, 'spa', 'Obtener, sacar a luz', 'Obtener o sacar a la luz, especialmente el favor divino, el sentido Hifil más frecuente. Pr 8:35 y 18:22 emparejan יָפִיק con מָצָא (''hallar''), describiendo a quien halla esposa o sabiduría como alguien que ''obtiene'' favor de YHWH. Pr 3:13 y 12:2 extienden esto a obtener entendimiento y benevolencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127283, 'spa', 'Proveer, derramar', 'Proveer, abastecer o derramar para otros: el sentido causativo de suministrar activamente. Sal 144:13 describe rebaños que ''proveen'' (מְפִיקִים) millares sobre millares, e Is 58:10 llama a derramar el alma por el hambriento. Este sentido extiende la raíz de ''sacar'' hacia la beneficencia activa y generosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127287, 'spa', 'Hacer prosperar planes', 'Promover, adelantar o hacer que los planes tengan éxito: un uso singular pero distintivo en Sal 140:8. El salmista ruega que Dios no ''haga prosperar'' (תָּפֵק) los designios del impío. La fuerza causativa es clara: no se trata meramente de obtener, sino de impulsar activamente los propósitos de alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127288, 'spa', 'Tropiezo de conciencia', 'Designa un obstáculo moral o escrúpulo de conciencia que hace tambalearse interiormente. En 1 Samuel 25:31, Abigail advierte a David contra crear un ''tropiezo'' (פּוּקָה) al vengarse derramando sangre, un acto que lo perseguiría y resultaría un impedimento al convertirse en rey. El término captura tanto la inestabilidad moral como el peso del remordimiento, expresando con precisión las consecuencias internas de una acción precipitada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127289, 'spa', 'Romper, frustrar, anular', 'Denota romper, frustrar o invalidar—especialmente pactos, planes o consejos. Salmo 33:10 declara que Dios ''frustra (מֵפֵר) el consejo de las naciones''. Salmo 89:33 (versículo 34 en hebreo) promete que Dios no ''romperá (אָפִיר) mi pacto'', usando una forma metaplástica. Ezequiel 17:19 condena al rey que ''rompió (הֵפִיר) mi pacto''. El verbo aparece frecuentemente con pacto (בְּרִית), consejo o propósito, implicando anulación autoritativa de lo establecido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127290, 'spa', 'Pur/Purim (suerte, fiesta)', 'Sustantivo que significa ''suerte'', probablemente préstamo del acadio puru (piedra para el sorteo). Usado exclusivamente en Ester, donde Amán echa el pur para fijar la fecha de su decreto genocida (Est 3:7; 9:24). El narrador lo glosa como haggoral (''la suerte''), indicando que requería explicación para lectores hebreos. El plural Purim nombra la festividad que celebra la liberación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127295, 'spa', 'Hijo de Amán', 'Nombre propio de origen persa que identifica a uno de los diez hijos de Amán muertos en Ester 9:8 durante la defensa de los judíos contra sus enemigos. La muerte de פּוֹרָתָא junto con sus hermanos representa el derrocamiento completo del complot genocida de Amán. Las versiones antiguas muestran variaciones ortográficas al intentar transcribir este nombre extranjero, y su presencia en la lista enfatiza la total inversión de la fortuna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127296, 'spa', 'Brincar con regocijo', 'Verbo que describe el acto de brincar, saltar o retozar con exuberancia, usado en Jeremías 50:11 para reprochar a Babilonia. El profeta se dirige a quienes saquearon a Israel: ''brincáis'' o actuáis como becerros que retozan despreocupadamente, celebrando la conquista. La imagen evoca ganado joven saltando de alegría. En español, ''engordasteis'' refleja una interpretación alternativa, pero el sentido primario es de movimiento festivo y desenfrenado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127297, 'spa', 'Saltar, retozar animadamente', 'Describe el salto animado, retozo o encabritamiento como animales jóvenes. Jeremías 50:11 reprende a Babilonia: ''retozáis (תָּפוּשׁוּ, Qere) como novilla''—celebrando la conquista presuntuosamente. Habacuc 1:8 describe caballos de guerra: ''se encabritan (וּפָשׁוּ)''—aunque algunos eliminan esto como ditografía. Malaquías 4:2 (3:20 en hebreo) promete que los justos ''saltarán (וּפִשְׁתֶּם) como becerros del establo'', expresando liberación gozosa y renovación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127298, 'spa', 'Ser dispersado', 'Verbo pasivo que significa ''ser dispersado'' o ''esparcido'', usado en Nahúm 3:18 para describir el destino del pueblo asirio. El profeta declara que los pastores (líderes) dormitan y el pueblo está esparcido por los montes sin nadie que lo congregue. Aunque textualmente incierto, el sentido es claro: dispersión completa y abandono, imagen del colapso definitivo de una nación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127299, 'spa', 'Gentilicio judaíta', 'La designación gentilicia ''putita'' (con artículo definido) identifica un clan de Judá mencionado en 1 Crónicas 2:53. Esta familia descendía de la línea de Quiriat-jearim y formaba parte de la compleja estructura tribal de Judá. Como muchos nombres similares en Crónicas, preservaba la identidad del clan aunque su historia y ubicación específicas ya no fueran ampliamente conocidas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127300, 'spa', 'Oro fino, oro puro', 'Oro refinado y puro de la más alta calidad, empleado como término poético y literario para expresar valor supremo y belleza. Se distingue del común זָהָב (oro) por su asociación con las comparaciones más elevadas: la Torá de Dios es más preciosa que el oro fino (Sal 19:10; 119:127), una corona real es de oro puro (Sal 21:3), el rendimiento de la Sabiduría lo supera (Pr 8:19) y la apariencia del amado se compara con él (Cnt 5:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127306, 'spa', 'Oro refinado', 'Participio Hofal que significa ''refinado'' o ''purificado'', describiendo el oro en 1 Reyes 10:18. El magnífico trono de Salomón fue revestido con ''oro refinado'', es decir, oro sometido a un proceso de purificación para eliminar impurezas y lograr la máxima calidad. El término subraya la pureza y el valor del metal precioso. Aunque la raíz es léxicamente incierta, el contexto indica claramente oro de calidad suprema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127308, 'spa', 'Esparcir, dispersar (Piel activo)', 'Dispersión activa en el tronco Piel, que subraya una acción deliberada y completa. Dios es el sujeto principal: esparce a los enemigos (Sal 53:5; 89:10), extiende la escarcha como ceniza (Sal 147:16) y dispersa naciones (Joel 3:2). El Piel intensivo indica que no se trata de un movimiento accidental, sino de una acción decidida. Proverbios 11:24 extiende la imagen a la distribución generosa de bienes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127312, 'spa', 'Ser dispersado (pasivo)', 'Dispersión pasiva expresada mediante el participio pasivo Qal, el Nifal y el Pual, que describen el estado de haber sido esparcido. Jeremías 50:17 emplea el participio femenino שֶׂה פְזוּרָה, «oveja dispersa», como imagen poderosa de Israel en el exilio. En el Salmo 141:7 los huesos yacen esparcidos junto a la boca del Seol, y Ester 3:8 describe a los judíos como «dispersos y diseminados» entre los pueblos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127318, 'spa', 'Trampa con resorte o lazo para atrapar aves, usado literalmente en la literatura', 'Trampa con resorte o lazo para atrapar aves, usado literalmente en la literatura sapiencial (Amós 3:5; Proverbios 7:23; Eclesiastés 9:12) y abrumadoramente como figura de peligros ocultos, conspiraciones y juicio ineludible. Los enemigos del salmista tienden un lazo en secreto (Salmo 140:5; 142:3; 119:110), Josué advierte que las naciones serán trampa (Josué 23:13), y la célebre tríada aliterativa פַּחַד-פַּחַת-פַּח (''terror, fosa, trampa'') en Isaías 24:17-18 y Jeremías 48:43-44 evoca un atrapamiento súbito e inescapable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127332, 'spa', 'Sentido estándar del Qal de temer, tener pavor o estar asustado — un temor de am', 'Sentido estándar del Qal de temer, tener pavor o estar asustado — un temor de amplio espectro dirigido a amenazas, enemigos o futuros inciertos. Deuteronomio 28:66-67 lo combina con acusativo cognado (''temerás con temor'') para describir el terror de la maldición del pacto. Job 3:25 y 23:15 muestran un pavor profundamente personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127335, 'spa', 'El Piel intensifica el temor en un estado sostenido y habitual de pavor', 'El Piel intensifica el temor en un estado sostenido y habitual de pavor. Proverbios 28:14 lo usa positivamente: ''bienaventurado el que siempre teme'', refiriéndose a quien mantiene una postura constante de cautela reverente. Isaías 51:13 lo emplea negativamente para el terror crónico ante un opresor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127339, 'spa', 'Uso intensificado del Qal que enfatiza la dimensión somática', 'Uso intensificado del Qal que enfatiza la dimensión somática: temblor físico, estremecimiento, terror que hace palpitar el corazón. Isaías 44:8, 11 lo usa retóricamente (''¡no tembléis!'') para contrastar el miedo de Israel con la soberanía de Dios. En Miqueas 7:17, las naciones ''salen temblando'' de sus fortalezas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127341, 'spa', 'Sentido reverencial donde el pavor se transforma en santo temor', 'Sentido reverencial donde el pavor se transforma en santo temor. En Salmo 119:161, el corazón del salmista ''tiembla de reverencia'' ante la palabra de Dios — no miedo al castigo, sino asombro reverente ante el discurso divino. Este sentido tiende un puente entre el terror y la adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127352, 'spa', 'El Hifil causativo', 'El Hifil causativo: hacer temblar a alguien, aterrorizar. Job 4:14 describe la visión nocturna de Elifaz: ''me sobrevino espanto... que hizo temblar todos mis huesos.'' La construcción causativa coloca la agencia en la experiencia aterradora misma, o en un agente divino detrás de ella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127354, 'spa', 'Pavor, terror, temor — La emoción subjetiva de pavor, terror o temor, el sentido', 'Pavor, terror, temor — La emoción subjetiva de pavor, terror o temor, el sentido dominante en 43 apariciones. Emparejado con יִרְאָה y מוֹרָא (Dt 2:25; 11:25), designa el estremecimiento que abruma a los enemigos ante Dios o Israel. Job lo siente apoderarse de sus huesos (Job 4:14), y la carne del salmista tiembla de temor ante Dios (Sal 119:120).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127356, 'spa', 'Calamidad repentina, desastre — Un evento concreto de calamidad repentina o desa', 'Calamidad repentina, desastre — Un evento concreto de calamidad repentina o desastre: la cosa temida en sí, no meramente la emoción. Proverbios advierte que «tu espanto» vendrá como tormenta (Pr 1:27; 3:25), y Job pregunta si alguien está libre de terrores repentinos (Job 15:21; 21:9). El matiz cambia del sentimiento al acontecimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127365, 'spa', 'Objeto de temor, Temor (epíteto divino) — Aquello que es temido', 'Objeto de temor, Temor (epíteto divino) — Aquello que es temido: un epíteto divino usado de manera única para Dios como «el Temor de Isaac» (Gn 31:42, 53). Jacob invoca no una emoción sino una Persona: el Ser imponente a quien su padre veneraba y por cuya autoridad sobrecogedora se sellan los pactos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127376, 'spa', 'Temor reverente', 'Se refiere al ''temor de mí'' o ''pavor de mí'' (Dios hablando) en Jeremías 2:19. El profeta declara que la maldad de Israel procede de carecer de la debida reverencia: ''no hay temor de mí en vosotros''. El término denota asombro religioso o reverencia, la respuesta apropiada ante la santidad de Dios que Israel ha perdido por la apostasía. El sufijo de primera persona subraya la dimensión personal de esta relación quebrantada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127377, 'spa', 'Gobernador o prefecto provincial designado sobre un distrito, empleado a lo larg', 'Gobernador o prefecto provincial designado sobre un distrito, empleado a lo largo de los períodos asirio, babilónico y persa. Préstamo del acadio (de bēl pāḥati, ''señor de una provincia'') que entra al hebreo para describir oficiales militares extranjeros (2 Reyes 18:24; Ezequiel 23:6, 12), administradores babilónicos (Jeremías 51:23, 28, 57) y gobernadores persas como Zorobabel (Hageo 1:1), Nehemías (Nehemías 5:14) y Tatnai (Esdras 5:3). Malaquías 1:8 lo usa para reprochar a Israel por ofrecer a Dios dones que no se atreverían a presentar a su propio gobernador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127390, 'spa', 'Gobernador provincial', 'Gobernador o funcionario provincial imperial, título de origen administrativo babilónico-persa (arameo פֶּחָה). Se usa en Esdras para los oficiales que gobernaban la provincia de Trans-Éufrates (Esd 5:3, 6; 6:6–7, 13) y para el custodio de los tesoros del templo (Esd 5:14), y en Daniel para los gobernadores provinciales reunidos ante la autoridad real (Dn 3:2–3, 27; 6:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127393, 'spa', 'Desenfreno temerario', 'Sustantivo que significa ''desenfreno'', ''temeridad'' o ''licencia desenfrenada'', usado en Génesis 49:4 para caracterizar a Rubén. Jacob declara «inestable como el agua» (פַּחַז כַּמַּיִם), empleando este término para describir la falta de dominio propio de Rubén. La palabra capta una conducta impulsiva y precipitada, sin la debida contención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127394, 'spa', 'Presunción temeraria', 'Se refiere a la temeridad o presunción jactanciosa de los falsos profetas en Jeremías 23:32. Dios declara que no envió a estos profetas, pero ellos extravían al pueblo «con su temeridad», hablando con confianza sin autoridad divina. El término enfatiza la presunción irresponsable y las pretensiones extravagantes de quienes hablan en nombre de Dios sin haber sido comisionados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127395, 'spa', 'Atrapamiento total', 'Infinitivo absoluto que significa «atrapado» o «enredado», usado en Isaías 42:22 para describir la cautividad de Israel. El texto declara que el pueblo de Dios ha sido «atrapado» (הָפֵחַ) en hoyos y escondido en prisiones, saqueado sin libertador. El verbo denominativo deriva de «trampa» o «lazo», y la forma del infinitivo absoluto intensifica el sentido: están completa y totalmente atrapados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127396, 'spa', 'Carbón, brasas ardientes', 'Se refiere a carbón o brasas resplandecientes usadas para sostener el fuego, particularmente en metalurgia o como combustible. Proverbios 26:21 declara ''el carbón (פֶּחָם) a las brasas y la leña al fuego''—el carbón provee calor intenso y duradero para las brasas. Isaías 44:12 describe al metalúrgico que ''trabaja en los carbones'' (בַּפֶּחָם), forjando hierro en el calor. Isaías 54:16 declara que Dios creó ''al herrero que sopla el fuego de carbones'' (אֵשׁ פֶּחָם), enfatizando el control divino sobre la artesanía humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127397, 'spa', 'Alfarero', 'Sustantivo arameo que significa «alfarero», quien trabaja con arcilla, apareciendo en Daniel 2:41. Es un préstamo lingüístico (probablemente del asirio paḫâru) usado en la sección aramea de Daniel. En el contexto del sueño de Nabucodonosor, el «barro de alfarero» simboliza la naturaleza frágil y dividida de un reino futuro: arcilla mezclada con hierro que no se adhiere.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127398, 'spa', 'Fosa, trampa, hoyo', 'Fosa u hoyo en el suelo, empleado concretamente para una excavación física (2 S 17:9; 18:17) y figuradamente para una calamidad ineludible. El término es conocido sobre todo por la fórmula profética aliterativa pachad-pachat-pach («espanto, fosa y trampa») en Is 24:17–18, Jer 48:43–44 y Lm 3:47, donde huir de un peligro solo precipita a la víctima en el siguiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127403, 'spa', 'Pajat-Moab (nombre propio)', 'Nombre propio compuesto que significa «gobernador de Moab», designando un gran clan judío postexílico. Regresaron de Babilonia con 2.812 miembros (Esd 2:6; Neh 7:11), enviaron miembros adicionales con Esdras (Esd 8:4), participaron en la reforma de esposas extranjeras (Esd 10:30) y ayudaron a reparar el muro de Jerusalén (Neh 3:11). Sellaron la renovación del pacto (Neh 10:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127405, 'spa', 'Corrosión textil', 'Se refiere específicamente al deterioro leproso que carcome tejidos hilados o tejidos de punto, descrito en Levítico 13:55 como parte del examen sacerdotal de prendas contaminadas. El término enfatiza la cualidad penetrante y corrosiva de la descomposición: no es una mera decoloración superficial, sino una consumición activa del material mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127406, 'spa', 'Topacio o crisólito', 'Topacio o crisólito, piedra preciosa de color amarillo-dorado y gran valor. Éxodo 28:17 y 39:10 la ubican en el pectoral del sumo sacerdote como la segunda piedra. Job 28:19 usa el «topacio de Cus» como ejemplo de extrema preciosidad, aunque inferior a la sabiduría. Ezequiel 28:13 la incluye entre las gemas en la imaginería del Edén. Todos los contextos destacan su rareza, belleza y valor para uso sagrado o real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127407, 'spa', 'Flores talladas abiertas', 'Flores abiertas o capullos tallados que decoraban la madera del templo. Las cuatro apariciones (1 Re 6:18, 29, 32, 35) describen los paneles y puertas de cedro esculpidos con calabazas y flores abiertas. La repetición enfatiza la ornamentación floral omnipresente que creaba una atmósfera edénica: el templo como paraíso donde Dios habita entre flores simbólicas que representan vida y bendición divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127408, 'spa', 'Exentos de deberes', 'Describe a los musicos levitas del templo que estaban liberados de otras obligaciones, segun 1 Cronicas 9:33 (lectura Ketiv). Estos individuos estaban funcionalmente ''libres'' o exentos porque su ministerio musical requeria dedicacion completa. El termino proviene de una raiz que significa separar o liberar, indicando un estatus especial: liberados de las obligaciones leviticas normales para consagrarse al canto sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127409, 'spa', 'Martillo de forja', 'Un martillo pesado, especialmente el martillo de forja usado por herreros para dar forma al metal caliente. Isaías 41:7 describe al artesano animando al herrero, mencionando ''el que golpea con el martillo'' (הַמַּחֲלִיק עִם־פַּטִּישׁ). Jeremías 23:29 pregunta retóricamente: ''¿No es mi palabra como fuego... y como martillo (וּכְפַטִּישׁ) que quebranta la piedra?''—enfatizando el poder de la palabra de Dios. Jeremías 50:23 lamenta cómo Babilonia, ''martillo de toda la tierra'', ha sido quebrantada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127411, 'spa', 'Escapar, escabullirse', 'Escabullirse o escapar — separación intransitiva ante un peligro o perseguidor. En 1 S 19:10, David esquiva la lanza de Saúl y ''se escapó'', eludiendo la muerte. El francés ''il glissa au loin'' (''se deslizó lejos'') capta vívidamente el movimiento de una fuga por muy poco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127412, 'spa', 'El que abre (la matriz)', '«El que abre» la matriz — la expresión constructa literal peter rechem, que pone el énfasis en el acto físico de abrir por primera vez el vientre materno. Éxodo 13:2 ordena: «Conságrame todo primogénito, todo el que abre la matriz entre los israelitas». El acento recae sobre el acontecimiento biológico del parto más que sobre el linaje o el rango.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127413, 'spa', 'Primogénito de', 'La misma frase constructa interpretada con énfasis en la condición consagrada del hijo o animal, más que en el acto físico. En Éxodo 34:19-20 y Números 18:15, el término funciona como cuasi-sinónimo de bekhor («primogénito»), centrándose en la identidad de la cría y su pertenencia a Dios. El español «primogénito de» capta este matiz de estatus sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127416, 'spa', 'Primogenito que abre', 'Se refiere al primogenito como ''el que abre la matriz'' en Numeros 8:16, donde Dios reclama a todo primogenito israelita como suyo por haber sido el primero en abrir el vientre materno. Esta forma constructa enfatiza el acto de abrir o irrumpir, conectando la primogenitura biologica con la obligacion sagrada. Los levitas son entregados a Dios como sustitutos de estos primogenitos, un elemento clave en la teologia sacrificial de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127417, 'spa', 'Ciudad egipcia sagrada', 'Ciudad egipcia mencionada en Ezequiel 30:17, conocida en griego como Bubastis y ubicada cerca de la moderna Zagazig. Su nombre significa ''Casa de Bastet'', la diosa con cabeza de gato que era la deidad patrona de la ciudad. Ezequiel la incluye en su profecia sobre la destruccion venidera de Egipto bajo Babilonia, donde ni siquiera las ciudades consagradas a los dioses egipcios escaparian del juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127418, 'spa', 'Ruina catastrófica', 'Denota ruina, desastre o calamidad catastrófica. Job 30:24 pregunta: ''¿No extiende uno su mano en un montón de ruinas (בְּעִי), o en su desastre (בְּפִידוֹ) clama por ayuda?'' Job 31:29 protesta su inocencia: ''¿Me he alegrado de la ruina (בְּפִיד) de mi enemigo?'' Proverbios 24:22 advierte: ''porque su calamidad (פִּידָם) vendrá de repente''—refiriéndose al desastre de parte de Dios y el rey contra los rebeldes. El sustantivo enfatiza la naturaleza repentina y devastadora de la catástrofe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127419, 'spa', 'Porciones grasas sacrificiales', 'Designa las porciones de grasa o trozos de animales sacrificiales mencionados en las ofrendas leviticas (contexto de Jueces 3:16, aunque es primariamente un termino levitico). Eran los trozos selectos de sebo —la grasa dura que rodea los organos— que se disponían sobre el altar como porcion de Dios. El termino ''bordes'' o ''piezas'' sugiere como estas secciones grasas se cortaban y separaban de la carne, representando las partes mas ricas de la ofrenda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127420, 'spa', 'Campamento antes del mar', 'Topónimo del campamento de Israel en la frontera oriental de Egipto antes del cruce del mar Rojo. Éxodo 14:2, 9 lo ubica entre Migdol y el mar, frente a Baal-zefón. Números 33:7-8 lo documenta en el itinerario del Éxodo. Las cuatro apariciones lo señalan como el punto decisivo para el milagro del mar: la última posición de Israel en territorio egipcio antes de la liberación divina a través de las aguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127422, 'spa', 'Comandante de Abimelec', 'Nombre personal del comandante del ejército que servía a Abimelec, rey de Gerar. Génesis 21:22 introduce a ''Abimelec y Ficol (פִיכֹל) comandante de su ejército'' acercándose a Abraham para un tratado. El versículo 32 nota que ''volvieron a la tierra de los filisteos'' después del pacto en Beerseba. Génesis 26:26 muestra a ''Abimelec... y Ficol comandante de su ejército'' viniendo a Isaac, sugiriendo o la misma persona décadas después o un título dinástico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127423, 'spa', 'Esposa secundaria de condición legal inferior, distinguida de la esposa plena (א', 'Esposa secundaria de condición legal inferior, distinguida de la esposa plena (אִשָּׁה) por derechos reducidos de herencia y divorcio para sus hijos. La institución aparece sin comentario moral en las narrativas patriarcales (Gn 22:24; 25:6; 35:22; 36:12), donde los hijos de las concubinas reciben regalos pero no la herencia principal. En el período monárquico, las פִּלַגְשִׁים se convierten en marca de poder real y en instrumento de reivindicación política del trono.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127438, 'spa', 'Gordura excesiva moral', 'Describe la grasa corporal excesiva en Job 15:27, usada por Elifaz para caracterizar al impio que se ha vuelto complaciente por su prosperidad. El termino aparece en paralelo con ''su grasa'', enfatizando no una abundancia saludable sino una superabundancia: la acumulacion desmedida que proviene de la autoindulgencia. La imagen de cubrirse el rostro con gordura sugiere estar cegado por la comodidad material, perdiendo toda sensibilidad moral y espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127439, 'spa', 'Nombre propio de origen egipcio (posiblemente ''el nubio'' o ''de piel oscura'') apl', 'Nombre propio de origen egipcio (posiblemente ''el nubio'' o ''de piel oscura'') aplicado a al menos dos figuras sacerdotales distintas. Principalmente, el nieto de Aarón por medio de Eleazar, celebrado por su intervención decisiva en Baal-peor que detuvo una plaga y aseguró un pacto eterno de sacerdocio (Números 25:7-13; Salmo 106:30). Aparece como enviado a las tribus orientales (Josué 22:13), sacerdote en Betel (Jueces 20:28) y ancestro de Esdras (Esdras 7:5). El segundo portador es hijo de Elí en Siló, cuya corrupción junto a su hermano Ofni provocó la caída del santuario y la captura del arca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127446, 'spa', 'Temblor de rodillas', 'Describe el temblor o vacilación de las rodillas en Nahúm 2:10, parte de la vívida representación profética del terror que se apodera de los habitantes de Nínive durante la caída de la ciudad. El término capta el estremecimiento involuntario cuando las rodillas no logran sostener el cuerpo ante un miedo extremo, junto a imágenes de corazones derretidos y rostros descoloridos que retratan el colapso físico total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127447, 'spa', 'Río del Edén', 'Uno de los cuatro ríos que fluían desde el Edén en Génesis 2:11, descrito como serpenteante por Havila, tierra de oro, resina aromática y piedras preciosas. Aunque su ubicación exacta es debatida, el Pisón representa el flujo de la bendición edénica: agua vivificante que alcanza tierras lejanas. El nombre posiblemente derive de una raíz que significa «brotar», reflejando su papel como portador de vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127449, 'spa', 'Frasco de aceite', 'Un recipiente pequeño o frasco para aceite, usado específicamente en ceremonias de unción real. 1 Samuel 10:1 describe a Samuel tomando ''un frasco de aceite'' (פַּךְ הַשֶּׁמֶן) y derramándolo sobre la cabeza de Saúl para ungirlo rey. 2 Reyes 9:1 tiene a Eliseo instruyendo a su siervo a ''tomar este frasco de aceite'' (פַּךְ הַשֶּׁמֶן הַזֶּה) para ungir a Jehú, y el versículo 3 le ordena ''derramar el aceite sobre su cabeza''. El tamaño modesto del recipiente subraya la sacralidad concentrada del acto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127450, 'spa', 'Goteo suave', 'Describe agua que brota o mana suavemente desde el umbral sur del templo en Ezequiel 47:2. El participio Piel enfatiza una filtración constante y apacible, no un chorro poderoso, sino agua que comienza como un mero goteo bajo el templo. Este modesto inicio hace más impactante el desarrollo de la visión, pues el goteo se convierte en un río caudaloso que lleva vida y sanidad a todo lo que toca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127451, 'spa', 'Familia postexílica', 'Nombre ancestral de una familia postexílica que significa «cazadora de gacelas». Esdras 2:57 y Nehemías 7:59 listan a los «hijos de Poqueret-hazebaim» entre los sirvientes del templo que regresaron del exilio. El nombre compuesto (arameo + hebreo) sugiere un origen ocupacional o simbólico, posiblemente indicando antepasados que cazaban o atrapaban gacelas. Los textos paralelos confirman la pertenencia de esta familia a la comunidad restaurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127452, 'spa', 'Maravillas, prodigios — El uso dominante', 'Maravillas, prodigios — El uso dominante: el participio Nifal נִפְלָאוֹת como sustantivo para las maravillas de Dios, actos prodigiosos de salvación, creación y juicio. Estas 44 apariciones forman el corazón del vocabulario de alabanza de Israel, desde el Éxodo (Éx 3:20) hasta los himnos del Salterio (Sal 77:11; 1 Cr 16:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127457, 'spa', 'Cumplir un voto especial — Infinitivo constructo intensivo Piel en contextos cul', 'Cumplir un voto especial — Infinitivo constructo intensivo Piel en contextos cultuales: cumplir o llevar a cabo un voto especial ya asumido. Las tres apariciones (Lv 22:21; Nm 15:3, 8) se refieren todas a presentar ofrendas para saldar un voto extraordinario, completando lo que fue consagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127458, 'spa', 'Ser maravilloso, ser admirable — Formas Nifal estativas o finitas que expresan q', 'Ser maravilloso, ser admirable — Formas Nifal estativas o finitas que expresan que algo es maravilloso, admirable o excepcional en calidad. El lamento de David de que el amor de Jonatán era «admirable, que superaba al amor de las mujeres» (2 S 1:26) y el «de parte de Jehová es esto, y es cosa maravillosa a nuestros ojos» del salmista (Sal 118:23) ejemplifican este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127459, 'spa', 'Ser demasiado difícil, exceder la capacidad — El sentido de estar más allá de la', 'Ser demasiado difícil, exceder la capacidad — El sentido de estar más allá de la capacidad humana: demasiado difícil, demasiado extraordinario para lograrse o comprenderse. Cuando Dios pregunta a Abraham «¿Hay algo que sea demasiado difícil para Jehová?» (Gn 18:14), la misma raíz que nombra las maravillas ahora nombra la imposibilidad. Jeremías 32:17 y Deuteronomio 30:11 refuerzan esta tensión teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127464, 'spa', 'Obrar prodigiosamente, hacer maravilloso — Hifil causativo', 'Obrar prodigiosamente, hacer maravilloso — Hifil causativo: obrar prodigiosamente o hacer algo maravilloso, con Dios o un agente produciendo activamente resultados extraordinarios. El ángel actúa «prodigiosamente» en el altar de Manoa (Jue 13:19), y Dios «hace maravillosa» su misericordia para David (Sal 31:21). Nueve apariciones captan la iniciativa divina en la obra de prodigios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127469, 'spa', 'Hacer un voto extraordinario — Formas Hifil en contextos de iniciación de votos', 'Hacer un voto extraordinario — Formas Hifil en contextos de iniciación de votos: hacer un voto extraordinario, apartar un compromiso votivo como algo que sobrepasa lo ordinario. Levítico 27:2 y Números 6:2 lo usan para el momento de consagración, cuando una persona dedica a sí misma o sus bienes a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127477, 'spa', 'Mostrarse maravilloso (contra alguien) — Una aparición singular en Job 10', 'Mostrarse maravilloso (contra alguien) — Una aparición singular en Job 10:16 donde Dios «se muestra maravilloso» contra Job, un uso reflexivo tipo Hitpael que transmite que Dios despliega su poder extraordinario en un contexto adversarial. Job percibe con angustia que el poder divino se ha vuelto contra él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127495, 'spa', 'Prodigio, maravilla', 'Algo extraordinario que excede la comprensión ordinaria — un prodigio o maravilla — usado casi siempre para los actos de Dios. Se aplica a las obras redentoras de YHWH en el Éxodo (Éx 15:11), a sus proezas recordadas en la adoración (Sal 77:11, 14; 78:12) y a su fidelidad incomprensible (Sal 88:10; 89:5). Isaías 9:5 lo aplica al rey mesiánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127502, 'spa', 'Maravilloso, incomprensible', 'Describe lo que es maravilloso, incomprensible o más allá de la capacidad humana de comprender. Jueces 13:18 tiene al ángel respondiendo a la pregunta de Manoa sobre su nombre: ''¿Por qué preguntas mi nombre? Es maravilloso (פִּלְאִי, ketiv)''—demasiado misterioso para revelarlo. El qere lee פֶּלִי, pero ambos indican algo extraordinario. Salmo 139:6 exclama sobre la omnisciencia de Dios: ''Tal conocimiento es demasiado maravilloso (פִּלְאִיָה) para mí, demasiado elevado, no puedo alcanzarlo''—reconociendo el conocimiento divino como trascendente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127503, 'spa', 'Clan de Rubén', 'Designación de clan en Números 26:5 para los descendientes de Palú, hijo de Rubén. Usado con el artículo definido («los paluitas»), identifica un grupo familiar reconocido dentro de la tribu de Rubén durante el censo en el desierto. Este censo determinaba no solo la fuerza militar sino también las porciones de herencia en la tierra prometida, por lo que la identidad de clan tenía importancia legal y territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127504, 'spa', 'Dividir o separar', 'Dividir o partir, ya sea física o conceptualmente. Génesis 10:25 y 1 Crónicas 1:19 usan el Nifal: «la tierra fue dividida» en tiempos de Péleg (dispersión lingüística y étnica). Job 38:25 describe a Dios abriendo canales para la lluvia (división física). Salmo 55:9 pide dividir (confundir) el habla de los enemigos (conceptual). El verbo abarca desde la división geográfica e hidráulica hasta la confusión lingüística.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127505, 'spa', 'Reino fragmentado', 'Participio pasivo arameo en Daniel 2:41 que describe el cuarto reino del sueño de Nabucodonosor como «dividido». El término indica fragmentación interna: un dominio exteriormente unificado pero interiormente partido, como hierro y barro que no pueden fusionarse verdaderamente. Esta división lo hace inestable a pesar de su fortaleza, un imperio poderoso pero vulnerable por no lograr cohesión genuina entre sus partes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127506, 'spa', 'Mitad temporal', 'Palabra aramea que significa ''mitad'', presente en Daniel 7:25 en la frase profetica ''un tiempo, tiempos y medio tiempo'', describiendo la duracion de la persecucion del cuerno pequeno. Esta ''mitad'' tiene profundo significado teologico: representa un periodo incompleto, un tiempo acortado por intervencion divina, asegurando que el mal no prevalecera indefinidamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127507, 'spa', 'Arroyo o canal de agua', 'Un arroyo, canal o acequia — un curso de agua dividido. Derivado de la raíz p-l-g (''partir, dividir''), el término designa agua corriente en contextos tanto naturales como figurados: los arroyos junto a los cuales florece el justo (Sal 1:3, eco en Prov 21:1), lágrimas abundantes (Lam 3:48, Sal 119:136), canales de aceite que representan prosperidad (Job 29:6), e incluso el canal de riego de Dios mismo (Sal 65:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127517, 'spa', 'Peleg (nombre propio)', 'Nombre masculino propio פֶּלֶג, que significa ''división'' o ''canal de riego'', dado porque ''en sus días fue dividida la tierra'' (Gn 10:25). Hijo de Eber y ancestro de Abraham mediante Reu, Serug, Nacor y Taré. Aparece en la Tabla de las Naciones (Gn 10:25), el linaje semita (Gn 11:16-19) y Crónicas (1 Cr 1:19, 25). La LXX traduce Φαλεκ/Φαλεγ.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127518, 'spa', 'Arroyos de abundancia', 'Designa corrientes o canales de liquido en Job 20:17, especificamente ''arroyos de aceite y miel'', imagen de abundancia lujosa que los impios nunca experimentaran pese a su prosperidad temporal. El termino evoca rios que fluyen no con simple agua sino con las sustancias mas ricas, representando la bendicion plena y desbordante que proviene solo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127519, 'spa', 'divisiones sacerdotales organizadas', 'Divisiones u órdenes organizadas, particularmente de sacerdotes y levitas para la rotación del servicio del templo. Jueces 5:15-16 lo usa en el cántico de Débora: ''en las divisiones (בִּפְלַגּוֹת) de Rubén hubo grandes resoluciones de corazón''—posiblemente divisiones militares o tribales. 2 Crónicas 35:5 instruye a los sacerdotes a ''estar en el lugar santo según las divisiones (לִפְלֻגּוֹת) de las casas paternas de vuestros hermanos''—turnos rotativos de servicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127520, 'spa', 'Turnos sacerdotales', 'Frase aramea que significa ''en sus divisiones'' en Esdras 6:18, describiendo la estructura organizativa de sacerdotes y levitas en el templo restaurado de Jerusalen. Indica los turnos o cursos tradicionales que se remontaban a la organizacion de David, donde grupos familiares servian por rotacion para mantener un culto ininterrumpido, garantizando orden y equidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127521, 'spa', 'Guarniciones metalicas belicas', 'Designa guarniciones de acero o hierro endurecido en los carros de guerra en Nahum 2:3, que producen un destello igneo durante los preparativos de batalla. El termino describe refuerzos metalicos u ornamentos que reflejaban la luz de manera dramatica al maniobrar los ejercitos, intensificando tanto la resistencia de los carros como el impacto psicologico sobre el enemigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127522, 'spa', 'Nombre propio personal', 'Nombre propio en Genesis 22:22 que identifica a uno de los ocho hijos de Nacor, hermano de Abraham, y Milca. Como sobrino de Abraham, Pildas formaba parte de la red familiar aramea centrada en el norte de Mesopotamia. Aunque no desempena ningun papel activo en la narrativa biblica, su inclusion en esta genealogia establece los vinculos de parentesco mas amplios de la familia abrahamica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127523, 'spa', 'Distinguir, apartar (Hifil)', 'Sentido causativo Hifil: distinguir, apartar o establecer una separación clara. Dios hace distinción entre Egipto e Israel en las narrativas de las plagas (Ex 8:22; 9:4; 11:7), y aparta al piadoso para sí mismo (Sal 4:3). El peso teológico es evidente: el poder de Dios se manifiesta en su capacidad soberana de separar y distinguir a su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127524, 'spa', 'Ser hecho maravillosamente', 'Sentido Nifal especializado que expresa ser hecho de modo maravilloso o prodigioso, no meramente ''apartado'' sino evocando asombro ante el resultado. En Sal 139:14 el salmista exclama ''fui hecho maravillosamente'': la formación pasiva apunta a la acción creadora divina, donde la separación se convierte en reverencia sagrada ante la complejidad de la propia existencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127525, 'spa', 'Ser distinguido (Nifal)', 'Nifal pasivo/reflexivo en contexto comunitario: ser distinguido o apartado como pueblo. En Ex 33:16 Moisés pregunta cómo se sabrá que Israel es distinto si la presencia de Dios no los acompaña. La identidad corporativa depende enteramente del favor visible de Dios para marcarlos como diferentes de todas las naciones de la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127527, 'spa', 'Mostrar maravillosamente (Hifil)', 'Sentido Hifil imperativo de mostrar algo de manera prodigiosa o maravillosa. En Sal 17:7 David pide a Dios que ''muestre maravillosamente'' su amor fiel: no es mera exhibición sino demostración extraordinaria que inspira asombro. Este sentido tiende un puente entre la raíz de ''separar/distinguir'' y la de ''maravilla/prodigio''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127530, 'spa', 'Nombre propio masculino', 'Falú (''distinguido''), segundo hijo de Rubén y ancestro del clan faluita. Aparece en cinco registros genealógicos que abarcan desde la migración patriarcal a Egipto (Gn 46:9), el linaje sacerdotal (Éx 6:14), el censo del desierto (Nm 26:5, 8) y la crónica tribal (1 Cr 5:3). Notablemente, su línea produce a Datán y Abiram de la rebelión de Coré (Nm 26:8-9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127531, 'spa', 'gentilicio erróneo', 'Una designación gentilicia que aparece en las listas de guerreros de Crónicas, ampliamente considerada como error textual. 1 Crónicas 11:27 identifica a ''Heles el pelonita'', pero 2 Samuel 23:26 dice ''el paltita'' (הַפַּלְטִי)—de Bet-pelet. 1 Crónicas 27:10 repite ''el pelonita'' para Heles. Similarmente, 1 Crónicas 11:36 llama a alguien ''el pelonita'' donde 2 Samuel 23:34 dice ''el gilonita'' (הַגִּלֹנִי). La forma consonantal sugiere confusión escribal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127532, 'spa', 'Hender, traspasar', 'Hender, abrir o traspasar con fuerza. Abarca el arar la tierra (Sal 141:7), el traspaso de riñones e hígado como figuras de ataque devastador (Job 16:13; Pr 7:23), el corte de calabazas dentro de una olla (2 R 4:39) y posiblemente la apertura del vientre en el parto (Job 39:3). El español ''atraviesa'' refleja el empuje violento direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127533, 'spa', 'Servir, adorar (a una deidad)', 'Servir o rendir culto a una deidad mediante devoción religiosa. Este verbo arameo (cognado del acadio palahu, ''temer, reverenciar'') aparece exclusivamente en Daniel y Esdras. En Daniel es el término clave en las narrativas de confrontación: los tres compañeros rehúsan adorar dioses extranjeros (Dn 3:12, 14, 17–18, 28), y Daniel persiste en servir a su Dios (Dn 6:17, 21). En Dn 7:14, 27 describe la adoración universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127539, 'spa', 'Rodaja, tajada, sección', 'Una rodaja, tajada o sección cortada de un todo mayor, ya sea una piedra de molino (la piedra superior o inferior, como en Jue 9:53, 2 Sam 11:21, Job 41:24) o una rodaja de fruta (granada en Cant 4:3, 6:7; torta de higos en 1 Sam 30:12). La raíz פלח porta el sentido de partir o hender, y el sustantivo derivado retiene esa imagen de separación de un todo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127543, 'spa', 'Nombre propio personal', 'Nombre personal en Nehemías 10:24 que identifica a uno de los líderes que sellaron el pacto de observancia de la Torá en la Jerusalén postexílica. Al estampar su sello, Pilha se unió a otros jefes de familia en asumir la responsabilidad corporativa por el compromiso de Israel con la Ley de Dios, representando la determinación de la comunidad de reconstruir sus fundamentos espirituales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127544, 'spa', 'Servicio cultual', 'Frase aramea que significa «para el servicio de» en Esdras 7:19, referida al culto y ministerio práctico del templo de Jerusalén. El rey persa emplea este término al autorizar la devolución de los vasos sagrados, reconociendo su propósito religioso. «Servicio» abarca aquí tanto la adoración litúrgica como las labores necesarias para mantener las operaciones del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127545, 'spa', 'El participio Piel usado como sustantivo', 'El participio Piel usado como sustantivo: ''libertador, rescatador.'' Funciona como epíteto divino, típicamente en discurso confesional o hímnico. En los grandes textos paralelos de 2 Samuel 22:2 y Salmo 18:2, ''mi libertador'' aparece junto a ''mi roca,'' ''mi fortaleza'' y ''mi escudo.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127546, 'spa', 'El Piel causativo', 'El Piel causativo: librar, rescatar o poner en libertad del peligro, enemigos o angustia. Es el sentido dominante, concentrado en los Salmos (17:13; 22:4-8; 31:1; 37:40; 71:2-4; 82:4; 91:14). La construcción suele combinarse con min (''de'') para especificar la fuente del peligro. Dios es casi siempre el sujeto, haciendo de este un verbo característico de oración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127548, 'spa', 'El sentido intransitivo o reflexivo del Qal', 'El sentido intransitivo o reflexivo del Qal: escapar, huir a un lugar seguro. Ezequiel 7:16 describe a los sobrevivientes que ''escapan'' a las montañas, y Job 23:7 imagina ser ''liberado'' mediante un argumento honesto. Este sentido pone en primer plano el movimiento propio del fugitivo en vez de la intervención de un rescatador externo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127549, 'spa', 'El Hifil causativo', 'El Hifil causativo: llevarse, arrebatar. Isaías 5:29 presenta a un león que ''se lleva'' la presa sin que nadie la rescate, y Miqueas 6:14 advierte que lo que guardes, Dios lo ''entregará a la espada.'' El Hifil aquí implica remoción forzosa, más allá de toda recuperación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127561, 'spa', 'Sentido físico especializado', 'Sentido físico especializado: dar a luz, asistir en el parto. Job 21:10 describe una vaca que ''pare sin abortar'' — la idea central de la raíz de ''hacer salir a salvo'' aplicada a la parición. Una sola atestación, pero la lógica semántica es transparente: el alumbramiento seguro desde el vientre es la forma más concreta del rescate de פלט.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127567, 'spa', 'Gentilicio geográfico', 'Designación gentilicia en 2 Samuel 23:26 que identifica a Helez como originario de Bet-pelet en el sur de Judá. Como uno de los treinta valientes de David, Helez llevaba este identificador geográfico como parte de su título formal. El término vincula la destreza militar con la identidad local, mostrando cómo los guerreros de élite de David procedían de todo el territorio de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127568, 'spa', 'Nombre sacerdotal', 'Nombre personal en Nehemías 12:17 que identifica al jefe de una familia sacerdotal durante el sumo sacerdocio de Joiaquim en la Jerusalén postexílica. La inclusión de Piltai en este registro genealógico servía para establecer la continuidad y legitimidad del sacerdocio reconstituido tras el exilio babilónico, documentando qué líneas sacerdotales mantenían su autorización para el servicio en el templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127570, 'spa', 'Nombre propio masculino', 'Nombre masculino propio que significa ''Yahvé ha librado''. Lo llevan múltiples personajes: un príncipe cívico en la visión de Ezequiel que muere como señal de juicio (Ez 11:1, 13), un descendiente postexílico de Zorobabel (1 Cr 3:21), un líder simeonita en la época de Ezequías (1 Cr 4:42) y un firmante del pacto (Neh 10:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127572, 'spa', 'Descendiente davídico', 'Nombre personal en 1 Crónicas 3:24 que identifica a un descendiente de David varias generaciones después del exilio babilónico. La inclusión de Pelaías en la genealogía real servía para documentar la continuación de la línea de David aun cuando ningún rey ocupaba el trono, preservando tanto el linaje legal como la esperanza mesiánica en el cumplimiento del pacto davídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127573, 'spa', 'Fugitivo, prófugo — Quien huye del peligro, la batalla o el castigo divino, con ', 'Fugitivo, prófugo — Quien huye del peligro, la batalla o el castigo divino, con énfasis en el acto de la fuga más que en sus consecuencias. Es el sentido más frecuente (14 ocurrencias), abarcando al mensajero que escapó para informar sobre la captura de Lot (Gn 14:13), la fórmula ''sin sobreviviente ni fugitivo'' de derrota militar total (Jos 8:22; Jer 42:17; 44:14; Lm 2:22), y los fugitivos efrateos en los vados del Jordán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127576, 'spa', 'Sobreviviente, remanente — Quien queda con vida tras una catástrofe, guerra o ju', 'Sobreviviente, remanente — Quien queda con vida tras una catástrofe, guerra o juicio divino, con énfasis en el estado de haber sobrevivido más que en el acto de escapar. Aparece 5 veces, notablemente en Is 45:20 (''ustedes fugitivos/sobrevivientes de las naciones''), Ez 6:8-9 (''tendréis sobrevivientes entre las naciones'' que recordarán al SEÑOR), Ez 7:16 (sobrevivientes en los montes gimiendo como palomas), y Abdías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127585, 'spa', 'Fugitivos o sobrevivientes', 'Fugitivos o escapados: los que sobreviven a una catastrofe militar o divina. El termino abarca tanto la huida como la supervivencia. Se aplica a los cautivos moabitas (Num 21:29), a los refugiados judios en Egipto de los que apenas alguno regresara (Jer 44:14), a los sobrevivientes de la destruccion de Babilonia que dan testimonio ante Sion (Jer 50:28; 51:50) y a los mensajeros escatologicos enviados a las naciones (Isa 66:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127586, 'spa', 'El grupo concreto de sobrevivientes o remanente que ha escapado de la destrucció', 'El grupo concreto de sobrevivientes o remanente que ha escapado de la destrucción, el juicio o la catástrofe — las personas o cosas que quedan en pie después de la devastación. Se usa para los sobrevivientes de las langostas (Éxodo 10:5), de la derrota militar (Jueces 21:17) y, de manera más prominente, del remanente de Judá después de los exilios asirio y babilónico (2 Reyes 19:30-31; Esdras 9:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127588, 'spa', 'El acto abstracto o medio de liberación del peligro, enfocándose en el escape mi', 'El acto abstracto o medio de liberación del peligro, enfocándose en el escape mismo más que en quienes escaparon. La planificación de Jacob ante Esaú (Génesis 32:8) y la lectura teológica de José sobre su propio viaje como provisión divina de escape (Génesis 45:7) ejemplifican este sentido. Se distingue del sentido 1 por designar la acción de escapar, no a los escapados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127609, 'spa', 'jueces legales', 'Jueces o árbitros legales que deciden casos y emiten sentencias. Éxodo 21:22 aborda lesiones a una mujer embarazada: el ofensor pagará ''según determinen los jueces (בִּפְלִלִים)''—arbitraje legal de daños. Deuteronomio 32:31 declara: ''siendo nuestros mismos enemigos jueces (פְלִילִים)''—incluso ellos deben conceder la supremacía de Yahvé sobre sus dioses. Job 31:11 describe el adulterio como ''una iniquidad para jueces''—un crimen que requiere sanción judicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127610, 'spa', 'Decisión judicial', 'Se refiere al acto de emitir decisiones o ejercer el oficio de juez o árbitro en Isaías 16:3, donde se exhorta a Moab a brindar protección judicial a los refugiados de Judá. El término enfatiza el aspecto funcional de la justicia: sopesar activamente los casos, pronunciar determinaciones y dictar veredictos que defiendan a los vulnerables. No es autoridad pasiva, sino arbitraje activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127611, 'spa', 'Delito enjuiciable', 'Adjetivo en Job 31:28 que describe una iniquidad bajo la jurisdicción de los jueces, un delito que requiere acción judicial formal. Job emplea esta expresión para caracterizar la idolatría no como mero pecado personal, sino como crimen público contra la comunidad del pacto que los tribunales terrenales deberían perseguir. El término distingue entre faltas privadas y violaciones tan graves que exigen un juicio legal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127612, 'spa', 'Emisión de juicio', 'Se refiere al acto de emitir juicio o tomar decisiones en Isaías 28:7, donde sacerdotes y profetas ebrios son condenados por titubear «en el juicio». El término describe la función esencial de discernir y decidir, ya se trate de veredictos judiciales o declaraciones proféticas. Los líderes espirituales de Israel tenían esta responsabilidad, y su embriaguez no solo los avergonzaba personalmente, sino que inhabilitaba su capacidad para guiar al pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127613, 'spa', 'Distrito administrativo', 'Un distrito o región administrativa, usado exclusivamente en Nehemías 3 para las subprovincias de la Judea postexílica cuyos gobernantes contribuyeron a la reconstrucción de la muralla de Jerusalén. El término aparece en formas constructas como פֶּלֶךְ בֵּית צוּר, ''distrito de Bet-sur'' (Neh 3:16), y פֶּלֶךְ מִצְפָּה, ''distrito de Mizpa'' (Neh 3:15). La noción subyacente puede ser un ''circuito'' de territorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127614, 'spa', 'Huso para hilar', 'Un huso o rueca utilizado en la producción textil para hilar hilo, representando el sentido concreto y físico de la palabra. En Proverbios 31:19, la mujer virtuosa ''extiende sus manos al פֶּלֶךְ'', emparejado con כִּישׁוֹר (rueca), dejando claro el contexto del hilado. En 2 Samuel 3:29, la maldición de David describe a hombres de la casa de Joab reducidos a ''sostener el huso'' — un insulto que implica debilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127617, 'spa', 'Orar (Hitpael) — El sentido abrumadoramente primario (80 de 84 apariciones)', 'Orar (Hitpael) — El sentido abrumadoramente primario (80 de 84 apariciones): orar, hacer súplica o interceder ante Dios en la raíz Hitpael. La forma reflexiva sugiere dirigirse uno mismo hacia Dios. Abarca todas las grandes oraciones bíblicas: intercesoras (Gn 20:17; Nm 21:7), penitenciales (Dt 9:26), dedicatorias (1 R 8:28) y desesperadas (2 R 19:15; Jon 2:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127631, 'spa', 'Juzgar, interceder (Piel) — Un uso raro en la raíz Piel (3 apariciones) que sign', 'Juzgar, interceder (Piel) — Un uso raro en la raíz Piel (3 apariciones) que significa juzgar, mediar o interceder en capacidad judicial o intercesora. En 1 Samuel 2:25 significa arbitrar una disputa; en Salmo 106:30, Finees «ejecutó juicio» para detener una plaga; en Ezequiel 16:52, Jerusalén «juzgó» (vindicó) a sus hermanas por su propio pecado mayor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127642, 'spa', 'Pensar, imaginar (uso aislado) — Una aparición única en Génesis 48', 'Pensar, imaginar (uso aislado) — Una aparición única en Génesis 48:11, donde Jacob dice «no había pensado ver tu rostro», con un significado cognitivo de calcular o esperar, probablemente un uso denominativo del sustantivo פְּלִילָה (evaluación judicial, cálculo). Este sentido aislado preserva un vínculo arcaico entre la deliberación judicial y la expectativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127653, 'spa', 'Nombre propio', 'Nombre personal en Nehemías 3:25 que identifica a uno de los constructores que repararon la muralla de Jerusalén tras el exilio babilónico. Palal trabajó en una sección cercana a la torre saliente y el palacio alto del rey. Como todos los constructores nombrados en este capítulo, su labor fue tanto práctica como simbólica: reconstruir las defensas físicas y demostrar la determinación de la comunidad restaurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127654, 'spa', 'Nombre sacerdotal', 'Nombre personal en Nehemías 11:12 que identifica a un sacerdote que servía en Jerusalén tras el regreso de Babilonia. Como hijo de Amsi, Pelalías formaba parte del establecimiento sacerdotal reconstituido en el templo restaurado. Su nombre, que significa algo como «Yahvé ha intervenido», refleja la convicción teológica que sustentaba estas genealogías: Dios había intervenido efectivamente para restaurar a su pueblo y su culto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127655, 'spa', 'A cierto uno', 'Frase aramea que significa «a cierto uno» o «a alguien» en Daniel 8:13, donde un ser santo habla a otro ser santo sin nombre. La vaguedad deliberada enfatiza la naturaleza misteriosa de la conversación angélica que Daniel presencia. Al no identificar a los interlocutores, el texto preserva la sensación de que Daniel capta un fragmento de discurso celestial que no estaba originalmente dirigido a él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127656, 'spa', 'pronombre indefinido', 'Un pronombre indefinido que significa ''fulano'' o ''cierto individuo'', usado cuando deliberadamente no se nombra a una persona o lugar. Rut 4:1 tiene a Boaz llamando al pariente más cercano: ''Apártate, amigo (פְּלֹנִי אַלְמֹנִי), siéntate aquí''—evitando su nombre (quizás porque falló en su deber). 1 Samuel 21:3 (versículo 2): ''el rey me ha encargado...encuéntrame en tal y tal lugar (מְקוֹם פְּלֹנִי אַלְמֹנִי)''. 2 Reyes 6:8 planea emboscada en ''tal lugar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127657, 'spa', 'Pesar, ponderar', 'Pesar, ponderar o evaluar, como si se colocase en una balanza. Se usa metafóricamente para el juicio moral: Salmo 58:2 acusa a los jueces de ''pesar violencia'' con sus manos, y Proverbios 5:6, 21 hablan de Dios ponderando los caminos de una persona. La imagen de la balanza subraya la idea de discernimiento y rendición de cuentas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127658, 'spa', 'Nivelar, allanar', 'Hacer llano o nivelar, dicho de preparar un camino o senda. Proverbios 4:26 ordena ''allana la senda de tus pies'', e Isaías 26:7 declara que Dios nivela el camino del justo. Este sentido se distingue del evaluativo al centrarse en la imagen de preparación de un camino, eliminando obstáculos para un tránsito recto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127664, 'spa', 'Estremecimiento cósmico', 'Verbo en Hitpael que describe el estremecimiento violento de los pilares de la tierra en Job 9:6, cuando Dios sacude el mundo. Expresa un temblor involuntario y convulsivo ante una fuerza abrumadora, no un balanceo suave sino una sacudida que amenaza la integridad estructural. Job usa esta imagen para subrayar el poder divino: ni los cimientos de la creación permanecen firmes cuando Dios manifiesta su poder.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127665, 'spa', 'Estremecimiento de horror', 'Estremecimiento o temblor causado por horror y terror. Job 21:6 describe el espanto apoderándose de la carne al recordar la aflicción. Salmo 55:5 lo empareja con temor y temblor que abruman al hablante. Isaías 21:4 narra el placer convertido en estremecimiento. Ezequiel 7:18 advierte que el pavor cubrirá todos los rostros en el juicio. El significado constante es un temblor físico involuntario ante un miedo extremo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127666, 'spa', 'Revolcarse en duelo', 'Revolcarse en polvo o ceniza como rito de luto, expresando profundo dolor o humillacion. El Hitpael subraya la naturaleza reflexiva y deliberada del acto. Ordenado como duelo profetico (Jer 6:26; 25:34), realizado por los marineros de Tiro en su lamentacion (Ez 27:30) y utilizado en un juego de palabras toponimico en Miqueas 1:10.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127667, 'spa', 'Filistea', 'Territorio de los filisteos en la costa suroeste de Canaán, usado exclusivamente en textos poéticos y tardíos. Aparece en el Cántico del Mar (Éx 15:14), en oráculos proféticos (Is 14:29, 31) y en varios salmos donde figura como enemigo sometido (Sal 60:10; 108:10; 83:8; 87:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127670, 'spa', 'filisteos (pueblo/nación)', 'Los filisteos como pueblo o nación colectiva, con 256 apariciones en los libros históricos y proféticos. Se usa en plural (פְּלִשְׁתִּים) con o sin artículo, en cadenas constructas como ''tierra de los filisteos'' (Gn 21:32) y ''señores de los filisteos'' (Jue 16:5). La evidencia interlingüística es uniforme: español ''filisteos'', francés ''Philistins'', alemán ''Philister'' lo tratan como gentilicio estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127671, 'spa', 'filisteo (individuo)', 'Un filisteo individual, con 33 apariciones exclusivamente en singular (הַפְּלִשְׁתִּי, ''el filisteo''). Casi todas se concentran en 1 Samuel 17-19, refiriéndose a Goliat como el célebre antagonista de David (1 S 17:8, 23, 26), con una referencia posterior a un filisteo muerto por Abisai (2 S 21:17). El español ''el filisteo'' y el francés ''le Philistin'' reflejan este artículo singular individualizante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127704, 'spa', 'nombre personal dudoso', 'Nombre personal que aparece en dos contextos genealógicos, uno probablemente erróneo. Números 16:1 lista a ''On hijo de Pelet (בֶּן־פֶּלֶת) hijo de Rubén'' entre los compañeros rebeldes de Coré. Sin embargo, On nunca reaparece en la narrativa, y los eruditos ampliamente proponen leer ''Falú'' (פַּלּוּא), un clan rubenita conocido (Génesis 46:9), en su lugar—una corrupción textual simple. 1 Crónicas 2:33 lista a ''Pelet'' como judahita, hijo de Jonatán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127705, 'spa', 'Los peleteos', 'Gentilicio que designa uno de los dos cuerpos de la guardia real de David, siempre emparejados con los cereteos. De origen probablemente filisteo o egeo, bajo el mando de Benaía servían como guardia personal y fuerza de choque. Permanecieron leales durante la rebelión de Absalón (2 Sam 15:18) y escoltaron a Salomón a su coronación (1 Re 1:38, 44).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127709, 'spa', 'Boca (arameo)', 'La boca física o abertura, usada en las porciones arameas de Daniel para la boca de un rey (Dan 4:31), de leones (Dan 6:22), de bestias apocalípticas (Dan 7:5, 8, 20) y la abertura sellada del foso de los leones (Dan 6:17). El español ''boca'' traduce directamente este término arameo que abarca tanto el habla como la contención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127713, 'spa', 'Esquinas territoriales', 'Se refiere a las esquinas o puntos angulares en Zacarías 14:10, definiendo la extensión de Jerusalén en la visión profética de la futura elevación de la ciudad. El término marca puntos límite donde los muros se encuentran y el territorio se delimita. Al nombrar esquinas específicas de puerta a puerta, Zacarías abarca la ciudad entera, sugiriendo una transformación completa. Las esquinas servían como puntos de referencia para describir totalidad geográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127714, 'spa', 'no sea que, para que no', 'Conjunción de propósito negativo o aprensión que introduce el resultado temido o indeseado de una acción: ''no sea que, para que no, no vaya a ser que''. Sigue a mandatos y advertencias para señalar lo que debe evitarse: ''no comáis de él, no sea que muráis'' (Gn 3:3); ''guárdate no sea que olvides'' (Dt 4:9; 8:11); ''no sea que extienda su mano'' (Gn 3:22). La partícula aparece siempre con verbo imperfecto, confiriéndole carácter de eventualidad futura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127720, 'spa', 'Producto alimenticio desconocido', 'Producto alimenticio no identificado mencionado en Ezequiel 27:17 entre los bienes comerciales que Judá e Israel suministraban a Tiro. Enumerado junto al trigo, la miel, el aceite y el bálsamo, era presumiblemente comestible y valioso, quizás confituras, tortas especiales o una preparación de grano. La incertidumbre sobre su identificación ha llevado a muchos traductores a simplemente conservar el término hebreo.');